    public init(kind: MessageKind, speaker: Speaker, text: String, responseID: String? = nil, draft_id: String? = nil) {
        self.kind = kind
        self.speaker = speaker
        self.text = text
        self.responseID = responseID
        self.draft_id = draft_id
    }
}

